mkdir -p $TMPDIR/check && cat > $TMPDIR/check/check.py <<'EOF'
import csv, sys, os, datetime as dt
from collections import Counter
D=sys.argv[1]; P=lambda s: dt.date.fromisoformat(s); VISIT=dt.date(2026,11,27)
n={}
def rd(f):
    with open(os.path.join(D,f),encoding='utf-8') as h:
        rows=list(csv.DictReader(l for l in h if not l.startswith('#')))
    n[f]=len(rows); return rows
C={r['id']:r for r in rd('contracts_register_2026.csv')}
reg=rd('registration_M1M2_2026.csv'); ot=rd('overtime_weekly_2026.csv'); pl=rd('payroll_lines_2026-07_to_10.csv')
att=rd('attendance_2026-11.csv'); runs=rd('payroll_runs_2026.csv'); leave={r['id']:r for r in rd('leave_decisions_2026.csv')}
abs_=rd('absences_2026.csv'); emp=rd('employee_records_2026.csv'); med=rd('medical_exams.csv'); tr=rd('training_proofs_2026.csv')
txt={}
for f in ['meldungen_ueberstunden_ordner.txt','sicherheitserklaerung_2019.md','ordner-index.md']:
    txt[f]=open(os.path.join(D,f),encoding='utf-8').read().splitlines()
F=[];G=[]
def add(rule,ids,num,unit): F.append((rule,sorted(set(ids)),num,unit))
# L02
late=[r['id'] for r in reg if P(r['date_filed'])>P(C[r['id']]['start_date'])-dt.timedelta(1)]
add('L02 M1/M2 nach dem Tag vor der ersten Schicht',late,len(late),'Personen')
for r in reg:
    d=(P(C[r['id']]['start_date'])-P(r['date_filed'])).days
    if 1<=d<=3: G.append(f"L02 {r['id']}: {d} Tage vor Beginn eingereicht, frist gewahrt")
reg_ids={r['id'] for r in reg}; miss=set(C)-reg_ids
if miss: add('L02 keine M1/M2',miss,len(miss),'Personen')
# L05
over=[r for r in ot if float(r['overtime_hours'])>8]
add('L05 Überstundenwochen über 8 h',[r['id'] for r in over],len(over),'Wochen')
for i,c in Counter(r['id'] for r in ot if 7<=float(r['overtime_hours'])<=8).items(): G.append(f"L05 {i}: {c} Wochen mit 7 bis 8 h, Grenze nicht überschritten")
# L06
m26=[l for l in txt['meldungen_ueberstunden_ordner.txt'] if l.startswith('2026') and '(leer)' not in l]
if not m26: add('L06 Überstundenwochen ohne Meldung',[r['id'] for r in ot if float(r['overtime_hours'])>0],sum(1 for r in ot if float(r['overtime_hours'])>0),'Wochen')
# L07
otm={(r['id'],r['week_start'][:7]) for r in ot if float(r['overtime_hours'])>0}
bad=[r for r in pl if (r['id'],r['month']) in otm and (r['overtime_line_hours'].strip() in ('','0'))]
add('L07 Lohnzeilen ohne Überstundenzeile',[r['id'] for r in bad],len(bad),'Lohnzeilen')
# L04
ab=[r for r in att if not(r['start'] and r['end'])]
noabs=[r for r in ab if r['code']!='ABS']
add('L04 Anwesenheitszeilen ohne Beginn und Ende',[r['id'] for r in noabs],len(noabs),'Zeilen')
absrows=[r for r in ab if r['code']=='ABS']
for a in abs_:
    k=sum(1 for r in absrows if r['id']==a['id'] and a['from']<=r['date']<=a['to'])
    G.append(f"L04 {a['id']}: {k} Zeilen ABS, gedeckt durch absences_2026.csv ({a['days']} Tage)")
# L08
def due(pe):
    d=P(pe)+dt.timedelta(15)
    while d.weekday()>=5: d+=dt.timedelta(1)
    return d
lp=[r for r in runs if P(r['pay_date'])>due(r['period_end'])]
add('L08 Lohn nach der Frist',[r['period_end'] for r in lp],len(lp),'Perioden')
for r in runs:
    if P(r['period_end'])+dt.timedelta(15)!=due(r['period_end']) and P(r['pay_date'])<=due(r['period_end']) and P(r['pay_date'])>P(r['period_end'])+dt.timedelta(15):
        G.append(f"L08 Periode {r['period_end']}: Zahltag {r['pay_date']}, Frist fiel auf Wochenende und verschob sich")
# L09
def add_months(d,m):
    y,mo=divmod(d.month-1+m,12); return dt.date(d.year+y,mo+1,min(d.day,28) if d.day>28 else d.day)
owed=[i for i,c in C.items() if add_months(P(c['start_date']),6)<=VISIT]
nod=[i for i in owed if i not in leave]; low=[i for i in owed if i in leave and int(leave[i]['days'])<20]
add('L09 kein Urlaubsbescheid',nod,len(nod),'Personen'); add('L09 Bescheid unter 20 Tagen',low,len(low),'Personen')
for i,c in C.items():
    s6=add_months(P(c['start_date']),6)
    if i not in owed: G.append(f"L09 {i}: 6 Monate erst am {s6}, am Prüftag nicht geschuldet")
    elif (s6-VISIT).days>-90 or (i in leave and int(leave[i]['days'])==20): G.append(f"L09 {i}: 6 Monate am {s6}, Bescheid {leave.get(i,{}).get('days','fehlt')} Tage")
# L03
ef=[(r['id'],k) for r in emp for k in r if k.startswith('f') and not r[k].strip()]
add('L03 leere Felder in Akten',[i for i,_ in ef],len(ef),'Felder')
mi=set(C)-{r['id'] for r in emp}
if mi: add('L03 keine Akte',mi,len(mi),'Personen')
# L12
lim=dt.date(2024,11,27)
old=[r['id'] for r in med if P(r['last_exam_date'])<lim]
add('L12 Untersuchung älter als 24 Monate',old,len(old),'Personen')
for r in med:
    if lim<=P(r['last_exam_date'])<=lim+dt.timedelta(30): G.append(f"L12 {r['id']}: Untersuchung {r['last_exam_date']}, {(P(r['last_exam_date'])-lim).days} Tage vor der Grenze")
mm=set(C)-{r['id'] for r in med}
if mm: add('L12 keine Untersuchung',mm,len(mm),'Personen')
# L10
listed={l[2:].strip() for l in txt['sicherheitserklaerung_2019.md'] if l.startswith('- ')}
roles=set(c['role'] for c in C.values()); mr=sorted(roles-listed)
add('L10 Stellenbezeichnungen fehlen: '+', '.join(mr),[i for i,c in C.items() if c['role'] in mr],len(mr),'Bezeichnungen')
# L13
new=[i for i,c in C.items() if P(c['start_date'])>=dt.date(2025,11,27)]
T={r['id']:r for r in tr}
lt=[i for i in new if i not in T or P(T[i]['training_date'])>P(C[i]['start_date'])]
add('L13 Unterweisung fehlt oder nach Einstellungstag',lt,len(lt),'Personen')
for i in new:
    if i in T: G.append(f"L13 {i}: Unterweisung {T[i]['training_date']}, Einstellung {C[i]['start_date']}, nicht später")
print('ZEILEN',n, {k:len(v) for k,v in txt.items()})
for f in F: print('FUND',*f)
for g in G: print('GRENZ',g)
print('SUMME',sum(n.values()),sum(1 for f in F if f[2]),len(G))
EOF
python3 -I $TMPDIR/check/check.py "$PWD"
